             tpd_A_Y : VitalDelayType01 := (0.119174 ns, 0.0258741 ns);
             tpd_B_Y : VitalDelayType01 := (0.114159 ns, 0.0267875 ns);
             tpd_C_Y : VitalDelayType01 := (0.0974422 ns, 0.0255178 ns);
             tpd_D_Y : VitalDelayType01 := (0.0685435 ns, 0.0211643 ns);

             XOn            : BOOLEAN := DefCombSpikeXOn;
             MsgOn          : BOOLEAN := DefCombSpikeMsgOn;
             instancePath   : STRING  := "*" );

   port (
         A : in std_ulogic := 'U' ;
         B : in std_ulogic := 'U' ;
         C : in std_ulogic := 'U' ;
