             tsetup_RN_CK_posedge_posedge : VitalDelayType := 0.376 ns;
             tsetup_RN_CK_negedge_posedge : VitalDelayType := 0.28225 ns;
             thold_RN_CK_posedge_posedge : VitalDelayType := -0.1885 ns;
             thold_RN_CK_negedge_posedge : VitalDelayType := -0.09475 ns;
             tsetup_E_CK_posedge_posedge : VitalDelayType := 0.329125 ns;
             tsetup_E_CK_negedge_posedge : VitalDelayType := 0.28225 ns;
