                    XOn            => DefSeqXOn,
                    MsgOn          => DefSeqMsgOn,
                    MsgSeverity    => WARNING );

                VitalSetupHoldCheck (
                    TestSignal     => D0_dly,
                    TestSignalName => "D0",
                    RefSignal      => CK_dly,
                    RefSignalName  => "CK",
                    SetupHigh      => tsetup_D0_CK_posedge_posedge,
                    SetupLow       => tsetup_D0_CK_negedge_posedge,
