                    MsgSeverity    => WARNING );

          END IF;


          -- Functionality section
          NOTIFIER := (
                        Tviol_SI_CK OR
                        Tviol_SE_CK OR
                        Tviol_S0_CK OR
                        Tviol_D1_CK OR
                        Tviol_D0_CK OR
